internal void IndustryUI(){Panel(new Rect(30,130,1860,755));Label(55,145,1200,55,"产业园 · "+c.ports[s.city].name,heading);for(int i=0;i<8;i++)if(Btn(55+i*224,220,211,52,c.industries[i]+" Lv"+s.cities[s.city].factories[i])){industry=i;scroll=Vector2.zero;}Label(60,290,1200,48,"有效工艺 "+g.Skills.EffectiveLevel(s,s.city,industry)+" / 20  ·  工坊 + 个人工艺 + 当班伙伴 + 城市加成",small);if(Btn(1400,290,450,48,"建造/升级 · "+c.factories[industry].price*(s.cities[s.city].factories[industry]+1)+" 金币"))Notify(g.Build(industry),7);var recipes=c.recipes.Where(r=>r.industry==industry).ToArray();scroll=GUI.BeginScrollView(new Rect(55,355,1070,490),scroll,new Rect(0,0,1030,recipes.Length*132));for(int i=0;i<recipes.Length;i++){var r=recipes[i];float y=i*132;Label(0,y,770,38,c.Product(r.output).name+" ×"+r.quantity+"  /  工艺"+r.minLevel+"  /  "+r.fee+"金币");Label(0,y+40,790,38,string.Join(" + ",r.inputs.Select(x=>c.Product(x.product).name+"×"+x.quantity+" [有"+g.Inventory.Count(s.cities[s.city].warehouse,x.product)+"]")),small);Label(0,y+80,790,37,r.foregroundSeconds+"秒 / "+r.awayCityMinutes+"分钟 / "+r.offlineHours+"小时 · 最差原料限定品质",small);if(Btn(820,y+20,190,60,"开始加工"))Notify(g.Start(r.id,s.city));}GUI.EndScrollView();Label(1160,348,630,42,"本城工单 · 亲临快 / 异城慢 / 离线更慢");var orders=s.orders.Where(o=>o.city==s.city&&!o.claimed&&!o.cancelled).ToArray();orderScroll=GUI.BeginScrollView(new Rect(1150,405,695,440),orderScroll,new Rect(0,0,655,orders.Length*160));for(int i=0;i<orders.Length;i++){var o=orders[i];float y=i*160;Label(10,y,640,36,c.Product(c.Recipe(o.recipe).output).name+"  "+(o.progress*100).ToString("0")+"% / "+(o.completed?"已完成":((1-o.progress)*g.Duration(o,false)).ToString("0")+"秒"),small);Fill(new Rect(10,y+45,620,8),new Color(.2f,.26f,.27f));Fill(new Rect(10,y+45,(float)o.progress*620,8),gold);if(Btn(10,y+67,180,48,o.completed?"领取成品":"取消退50%"))Notify(o.completed?g.Claim(o.id):g.Cancel(o.id));if(Btn(205,y+67,200,48,"续单 "+(o.repeat?"开":"关")))o.repeat=!o.repeat;if(Btn(420,y+67,200,48,"代售 "+(o.autoSell?"开":"关")))o.autoSell=!o.autoSell;}GUI.EndScrollView();}
internal void WarehouseUI(){Panel(new Rect(30,130,1860,755));var warehouse=s.cities[s.city].warehouse;Label(55,148,1200,60,"仓库与船舱 · 品质批次独立",heading);Label(60,227,1200,45,"船舱 "+g.Inventory.Weight(s.cargo)+" / "+s.cargo.capacity+"      仓库 "+g.Inventory.Weight(warehouse)+" / "+warehouse.capacity);if(Btn(1420,225,420,50,"扩建仓库 +100 / 200金币")){Notify(g.ExpandWarehouse());}var entries=s.cargo.batches.Select(b=>b.product+":"+b.quality).Concat(warehouse.batches.Select(b=>b.product+":"+b.quality)).Distinct().ToArray();scroll=GUI.BeginScrollView(new Rect(55,310,1780,540),scroll,new Rect(0,0,1730,entries.Length*76));for(int i=0;i<entries.Length;i++){string[] bits=entries[i].Split(':');string p=bits[0];int q=int.Parse(bits[1]);float y=i*76;Label(5,y+12,540,48,c.Product(p).name+" · 品质"+GameService.QualityName(q));Label(550,y+12,330,48,"船 "+g.Inventory.Count(s.cargo,p,q)+" / 仓 "+g.Inventory.Count(warehouse,p,q));if(Btn(950,y+5,350,54,"卸货 → 仓库 ×"+quantity))Notify(g.Inventory.Transfer(s.cargo,warehouse,p,q,quantity));if(Btn(1320,y+5,350,54,"装货 → 船舱 ×"+quantity))Notify(g.Inventory.Transfer(warehouse,s.cargo,p,q,quantity));}GUI.EndScrollView();if(Btn(1000,145,160,52,"数量 −"))quantity=Math.Max(1,quantity-1);Label(1190,157,90,45,quantity.ToString());if(Btn(1290,145,160,52,"数量 +"))quantity=Math.Min(80,quantity+1);}
